'use strict';
const DATA = window.WORKBOOK_DATA;
const ROLES = ['Supervisor','Technician','HSE Supervisor'];
const PERMISSIONS = Object.freeze({
  Supervisor: {pages:['dashboard','hse','downtime','parts','setup','access'],exports:['operations','downtime','parts','setup'],finance:true},
  Technician: {pages:['dashboard','hse','parts','setup'],exports:[],finance:false},
  'HSE Supervisor': {pages:['dashboard','hse','setup','access'],exports:['hse'],finance:false}
});
const PAGES = [['dashboard','grid','Dashboard'],['hse','shield','HSE Actions'],['downtime','chart','Downtime'],['parts','box','Parts Readiness'],['setup','book','Setup & Training'],['access','users','Access & Activity']];
const STAGES = [['detect_hours','Detection'],['dispatch_hours','Dispatch'],['parts_wait_hours','Parts wait'],['repair_hours','Repair'],['restart_hours','Restart']];
const PATHS={grid:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M9 12l2 2 4-4',chart:'M4 3v17h17 M8 16v-5 M13 16V6 M18 16V9',box:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',book:'M12 5C8 2 3 4 3 4v15s5-2 9 1c4-3 9-1 9-1V4s-5-2-9 1z M12 5v15',users:'M16 21v-3c0-3-8-3-8 0v3 M12 4a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M3 18v-2c0-2 2-3 4-3 M21 18v-2c0-2-2-3-4-3',search:'M10 3a7 7 0 1 0 0 14 7 7 0 1 0 0-14 M15 15l6 6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 11v6 M12 7v1',alert:'M12 3L2 21h20z M12 9v5 M12 17v1',check:'M4 12l5 5 11-11',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${PATHS[n]||PATHS.grid}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(n,d=1)=>n==null?'—':Number(n).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const money=n=>n==null?'—':Number(n).toLocaleString('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0});
const date=s=>!s?'—':new Date(s).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const sum=(rows,key)=>Math.round(rows.reduce((a,r)=>a+(Number(r[key])||0),0)*1e8)/1e8;
const byId=(rows,id,key)=>rows.find(r=>r[key]===id);
const siteName=id=>byId(DATA.sites,id,'site_id')?.site_name||id;
const main=document.getElementById('main'), modal=document.getElementById('modal');
let state={role:'Supervisor',site:'all',hseStatus:'Open',hseSeverity:'all',asset:'all',page:0},current='dashboard',timer;
try {const saved=JSON.parse(sessionStorage.getItem('field-operations-view-v3')||'null');if(saved){state.role=ROLES.includes(saved.role)?saved.role:'Technician';state.site=saved.site==='all'||DATA.sites.some(s=>s.site_id===saved.site)?saved.site:'all';}} catch {state.role='Technician';}
const allowed=p=>PERMISSIONS[state.role].pages.includes(p), canExport=k=>PERMISSIONS[state.role].exports.includes(k);
const selectedSites=()=>DATA.sites.filter(s=>state.site==='all'||s.site_id===state.site);
const scoped=rows=>rows.filter(r=>state.site==='all'||r.site_id===state.site);
const selectedAssets=()=>scoped(DATA.assets);
const events=()=>scoped(DATA.events).filter(e=>e.event_type==='Unplanned'&&(state.asset==='all'||e.asset_id===state.asset));
const hazards=()=>scoped(DATA.hse);
const openHazards=()=>hazards().filter(h=>h.action_status==='Open');
const criticalHazards=()=>openHazards().filter(h=>h.potential_severity===5);
function saveView(){try{sessionStorage.setItem('field-operations-view-v3',JSON.stringify({role:state.role,site:state.site}));}catch{}}
function badge(label,type='neutral'){return `<span class="badge ${type}">${esc(label)}</span>`;}
function stat(label,value,sub='',type=''){return `<div class="stat ${type}"><label>${type==='critical'?icon('alert'):''}${esc(label)}</label><div class="value">${value}</div>${sub?`<small>${esc(sub)}</small>`:''}</div>`;}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${esc(title)}</h2>${action}</div>${body}</section>`;}
function table(headers,rows){return `<div class="table-wrap compact"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">No records in this selection</td></tr>`}</tbody></table></div>`;}
function viewButton(kind,id,label='View'){return `<button class="btn secondary small" data-action="record" data-kind="${kind}" data-id="${esc(id)}">${label}</button>`;}
function siteButton(s){return `<button class="help-link" data-action="site" data-id="${s.site_id}">${esc(s.site_name)}</button>`;}
function meta(detail='2025 operations'){return `<div class="meta-row"><span>${state.site==='all'?'All sites · '+selectedSites().length+' sites':esc(siteName(state.site))+' · '+state.site}<span>·</span>${esc(detail)}</span><span class="role-label">${esc(state.role)} view</span></div>`;}
function bars(rows,unit='h'){const max=Math.max(...rows.map(r=>r[1]),1);return `<div class="panel-body bar-list mini-bars">${rows.map(([l,v])=>`<div class="bar-item"><span>${esc(l)}</span><div class="bar-track"><div class="bar-fill" style="width:${v/max*100}%"></div></div><strong>${num(v,unit==='h'?1:0)} ${unit}</strong></div>`).join('')}</div>`;}
function pager(total,size=6){const pages=Math.max(1,Math.ceil(total/size));state.page=Math.min(state.page,pages-1);return `<div class="table-footer"><span>${total?state.page*size+1:0}–${Math.min(total,(state.page+1)*size)} of ${total}</span><div><button class="btn small secondary" data-action="previous" ${state.page===0?'disabled':''}>Previous</button> <button class="btn small secondary" data-action="next" ${state.page>=pages-1?'disabled':''}>Next</button></div></div>`;}
function slice(rows,size=6){state.page=Math.min(state.page,Math.max(0,Math.ceil(rows.length/size)-1));return rows.slice(state.page*size,(state.page+1)*size);}
function stats(...cards){return `<div class="stats">${cards.join('')}</div>`;}
function recentSafety(limit=3){const rows=hazards().filter(h=>h.closed_date).sort((a,b)=>b.closed_date.localeCompare(a.closed_date)).slice(0,limit);return rows.length?`<div class="activity-list">${rows.map(h=>`<div class="activity-row"><span class="avatar">${esc(h.site_id)}</span><div class="activity-text"><strong>${esc(h.hse_id)} · ${esc(h.hazard)}</strong><div class="subtle">${esc(siteName(h.site_id))} · Closed in source</div></div><time class="time">${date(h.closed_date)}</time></div>`).join('')}</div>`:'<div class="empty">No closed actions in this selection</div>';}
function safetyRows(rows,compact=false){return rows.map(h=>`<tr><td><strong>${esc(h.hse_id)}</strong>${compact?'':`<div class="subtle">${esc(h.asset_id)}</div>`}</td><td>${esc(siteName(h.site_id))}</td><td class="wrap-cell">${esc(h.hazard)}</td><td>${badge(h.potential_severity+' / 5',h.potential_severity===5?'critical':h.potential_severity>=3?'warning':'neutral')}</td><td>${date(h.due_date)}</td><td>${badge(h.action_status,h.action_status==='Open'?'warning':'success')}</td><td>${viewButton('hse',h.hse_id, state.role==='HSE Supervisor'?'Review':'View')}</td></tr>`);}
function fieldDashboard(){const a=selectedAssets(),h=openHazards(),sites=selectedSites();const rows=slice(a);return meta()+stats(stat('Equipment',a.length,'Workbook asset register'),stat('Open safety actions',h.length,'Source status','critical'),stat('Parts wait',num(sum(events(),'parts_wait_hours'))+' h','2025 unplanned events'),stat('Missing readings',sum(sites.map(s=>s.readings.quality_counts),'Missing'),'2025 daily records'))+`<div class="grid-main">${panel('Equipment',table(['Asset','Site','Equipment','Latest state','Reading'],rows.map(a=>`<tr><td><strong>${a.asset_id}</strong></td><td>${esc(siteName(a.site_id))}</td><td>${esc(a.asset_type)}</td><td>${esc(a.latest.operating_state)}</td><td>${viewButton('asset',a.asset_id)}</td></tr>`))+pager(a.length),badge('Latest records · '+date(DATA.assets.map(a=>a.latest.observed_utc).sort().at(-1))))}${panel('Open safety actions',`<div class="panel-body">${h.sort((a,b)=>b.potential_severity-a.potential_severity).slice(0,4).map(h=>`<div class="task-row"><div><strong>${esc(h.hazard)}</strong><div class="subtle">${esc(siteName(h.site_id))} · ${h.hse_id}</div></div>${viewButton('hse',h.hse_id)}</div>`).join('')||'<div class="empty">No open actions</div>'}</div>`,`<a href="#hse">View all</a>`)}</div>`+panel('Network uptime',`<div class="metric-strip">${sites.map(s=>`<div><span>${esc(s.site_name)}</span><strong>${num(s.network_uptime_pct)}%</strong></div>`).join('')}</div>`);}
function safetyDashboard(){const hs=hazards(),open=openHazards(),sites=selectedSites();return meta('HSE snapshot · '+date(DATA.meta.hseAsOf))+stats(stat('Critical open actions',criticalHazards().length,'Severity 5','critical'),stat('Open actions',open.length),stat('Closed actions',hs.filter(h=>h.action_status==='Closed').length),stat('Remediation effort',num(sum(open,'action_person_hours'),0)+' h','Open actions'))+`<div class="grid-main">${panel('HSE by site',table(['Site','Open','Critical','Closed','Action hours'],sites.map(s=>{const h=hs.filter(h=>h.site_id===s.site_id),o=h.filter(h=>h.action_status==='Open');return `<tr><td>${siteButton(s)}</td><td>${o.length}</td><td>${badge(o.filter(h=>h.potential_severity===5).length,o.some(h=>h.potential_severity===5)?'critical':'neutral')}</td><td>${h.filter(h=>h.action_status==='Closed').length}</td><td>${num(sum(o,'action_person_hours'),0)} h</td></tr>`;})))}${panel('Open actions by severity',bars([5,4,3,2,1].map(n=>['Severity '+n,open.filter(h=>h.potential_severity===n).length]),''))}</div>`+panel('Latest safety closures',recentSafety(3),`<a href="#hse">View actions</a>`);}
function dashboard(){if(state.role==='Technician')return fieldDashboard();if(state.role==='HSE Supervisor')return safetyDashboard();const e=events(),sites=selectedSites();return meta()+stats(stat('Sites',sites.length,selectedAssets().length+' assets'),stat('Unplanned downtime',num(sum(e,'stopped_hours'))+' h','Equipment-hours · 2025'),stat('Parts-wait hours',num(sum(e,'parts_wait_hours'))+' h',num(sum(e,'parts_wait_hours')/sum(e,'stopped_hours')*100)+'% of downtime'),stat('Critical HSE actions',criticalHazards().length,'Open · severity 5','critical'))+`<div class="grid-main">${panel('Site overview',table(['Site','Downtime','Parts wait','Spare fill','Network','Open HSE'],sites.map(s=>{const ev=e.filter(e=>e.site_id===s.site_id);return `<tr><td>${siteButton(s)}</td><td>${num(sum(ev,'stopped_hours'))} h</td><td>${num(sum(ev,'parts_wait_hours'))} h</td><td>${num(s.spare_fill_pct,0)}%</td><td>${num(s.network_uptime_pct)}%</td><td>${badge(openHazards().filter(h=>h.site_id===s.site_id).length)}</td></tr>`;})),badge('2025'))}${panel('Downtime stages',bars(STAGES.map(([key,label])=>[label,sum(e,key)])),`<a href="#downtime">Details</a>`)}</div>`+panel('Latest monthly production',`<div class="metric-strip">${sites.map(s=>{const p=DATA.production.filter(p=>p.site_id===s.site_id&&p.month===DATA.production.map(p=>p.month).sort().at(-1));return `<div><span>${esc(s.site_name)}</span><strong>${num(sum(p,'produced_oil_bbl'),0)} <small>bbl</small></strong></div>`;}).join('')}</div>`,badge(new Date(DATA.production.map(p=>p.month).sort().at(-1)).toLocaleDateString('en-US',{month:'long',year:'numeric',timeZone:'UTC'})));}
function hse(){const h=hazards(),open=openHazards();const filtered=h.filter(h=>(state.hseStatus==='all'||h.action_status===state.hseStatus)&&(state.hseSeverity==='all'||h.potential_severity===Number(state.hseSeverity))).sort((a,b)=>b.potential_severity-a.potential_severity||a.due_date.localeCompare(b.due_date));return meta('HSE snapshot · '+date(DATA.meta.hseAsOf))+stats(stat('Critical open actions',criticalHazards().length,'Severity 5','critical'),stat('Open actions',open.length),stat('Closed actions',h.filter(h=>h.action_status==='Closed').length),stat('Remediation effort',num(sum(open,'action_person_hours'),0)+' h','Open source actions'))+`<div class="tab-controls"><label>Status <select id="hse-status">${['Open','Closed','all'].map(v=>`<option value="${v}" ${state.hseStatus===v?'selected':''}>${v==='all'?'All statuses':v}</option>`).join('')}</select></label><label>Severity <select id="hse-severity"><option value="all">All severities</option>${[5,4,3,2,1].map(v=>`<option value="${v}" ${state.hseSeverity===String(v)?'selected':''}>${v}</option>`).join('')}</select></label><span class="subtle">${state.role==='HSE Supervisor'?'Review source evidence':'Read-only source records'}</span></div>`+panel('Corrective actions',table(['ID / asset','Site','Hazard','Severity','Due date','Status',''],safetyRows(slice(filtered)))+pager(filtered.length));}
function downtime(){const e=events(),hours=sum(e,'stopped_hours');const causes=[...new Set(e.map(e=>e.cause))].map(c=>[c,sum(e.filter(e=>e.cause===c),'stopped_hours')]).sort((a,b)=>b[1]-a[1]);const sorted=[...e].sort((a,b)=>b.stopped_hours-a.stopped_hours);return meta()+`<div class="tab-controls"><label>Equipment <select id="asset-scope"><option value="all">All equipment</option>${selectedAssets().map(a=>`<option value="${a.asset_id}" ${state.asset===a.asset_id?'selected':''}>${a.asset_id} · ${esc(siteName(a.site_id))}</option>`).join('')}</select></label><span class="subtle">Unplanned events only</span></div>`+stats(stat('Unplanned downtime',num(hours)+' h'),stat('Unplanned events',e.length),stat('Average duration',num(e.length?hours/e.length:0)+' h','Per event'),stat('Parts wait share',num(hours?sum(e,'parts_wait_hours')/hours*100:0)+'%'))+`<div class="grid-two">${panel('Downtime by stage',bars(STAGES.map(([k,l])=>[l,sum(e,k)])))}${panel('Downtime by cause',bars(causes))}</div>`+panel('Longest events',table(['Event','Site','Asset','Cause','Downtime','Parts wait',''],slice(sorted,3).map(e=>`<tr><td>${e.event_id}</td><td>${esc(siteName(e.site_id))}</td><td>${e.asset_id}</td><td>${esc(e.cause)}</td><td>${num(e.stopped_hours)} h</td><td>${num(e.parts_wait_hours)} h</td><td>${viewButton('event',e.event_id)}</td></tr>`))+pager(sorted.length,3));}
function parts(){const e=events(),parts=e.filter(e=>e.parts_wait_hours>0),sites=selectedSites(),fill=sites.map(s=>s.spare_fill_pct);const range=Math.min(...fill)===Math.max(...fill)?num(fill[0],0):num(Math.min(...fill),0)+'–'+num(Math.max(...fill),0);return meta()+stats(stat('Parts-wait hours',num(sum(e,'parts_wait_hours'))+' h'),stat('Events with parts waits',parts.length,'2025 unplanned events'),stat('Local spare fill',range+'%',sites.length>1?'Range across selected sites':'Site source rate'),stat('Downtime share',num(sum(e,'parts_wait_hours')/sum(e,'stopped_hours')*100)+'%','Parts-wait stage'))+panel('Parts readiness by site',table(['Site','Local spare fill','Parts wait','Affected events','Share of downtime',''],sites.map(s=>{const ev=e.filter(e=>e.site_id===s.site_id);return `<tr><td>${siteButton(s)}</td><td><div class="allocation"><span>${num(s.spare_fill_pct,0)}%</span><div class="progress"><span style="width:${s.spare_fill_pct}%"></span></div></div></td><td>${num(sum(ev,'parts_wait_hours'))} h</td><td>${ev.filter(e=>e.parts_wait_hours>0).length}</td><td>${num(sum(ev,'parts_wait_hours')/sum(ev,'stopped_hours')*100)}%</td><td>${viewButton('site',s.site_id)}</td></tr>`;})))+panel('Longest parts waits',table(['Event','Site','Asset','Cause','Parts wait',''],[...parts].sort((a,b)=>b.parts_wait_hours-a.parts_wait_hours).slice(0,2).map(e=>`<tr><td>${e.event_id}</td><td>${esc(siteName(e.site_id))}</td><td>${e.asset_id}</td><td>${esc(e.cause)}</td><td>${num(e.parts_wait_hours)} h</td><td>${viewButton('event',e.event_id)}</td></tr>`)),badge('Source event records'));}
function setup(){
  const sites=selectedSites(),o=byId(DATA.options,'O6','option_id'),supervisor=state.role==='Supervisor';
  const requirements=table(['Site','Technicians','Hours / person','Total training','Project capacity','Network'],sites.map(s=>`<tr><td>${siteButton(s)}</td><td>${s.technicians}</td><td>${s.training_hours_per_person} h</td><td>${num(s.training_required_hours,0)} h</td><td>${s.available_project_hours} h</td><td>${num(s.network_uptime_pct)}%</td></tr>`));
  const configuration=supervisor?`<div class="panel-body"><div class="allocation-line"><span>Cleanup setup</span><strong>${money(sum(sites,'cleanup_setup_usd'))}</strong></div><div class="allocation-line"><span>Edge setup</span><strong>${money(sum(sites,'edge_setup_usd'))}</strong></div><div class="allocation-line"><span>Annual edge cost</span><strong>${money(sum(sites,'edge_annual_usd'))}</strong></div><div class="source-line">Workbook inputs · selected sites</div></div>`:`<div class="panel-body"><div class="allocation-line"><span>Missing readings</span><strong>${sum(sites.map(s=>s.readings.quality_counts),'Missing')}</strong></div><div class="allocation-line"><span>Suspect readings</span><strong>${sum(sites.map(s=>s.readings.quality_counts),'Suspect')}</strong></div><div class="allocation-line"><span>Received over 1 hour late</span><strong>${sum(sites.map(s=>s.readings),'delayed_over_1h_count')}</strong></div><div class="source-line">Readings sheet · 2025 daily records</div></div>`;
  const training=`<div class="panel-body"><div class="allocation-line"><span>Lead time</span><strong>${o.lead_months} month</strong></div><div class="allocation-line"><span>Required for</span><strong>O1 or O3</strong></div>${supervisor?`<div class="allocation-line"><span>Setup / annual per site</span><strong>${money(o.setup_usd)} / ${money(o.annual_usd)}</strong></div>`:''}<div class="source-line">Solutions · ${o.source.cells.option_name}</div><button class="btn secondary small" data-action="record" data-kind="option" data-id="O6">View requirements</button></div>`;
  return meta('Workbook requirements')+stats(stat('Technicians',sum(sites,'technicians')),stat('Required training',num(sum(sites,'training_required_hours'),0)+' h','Technicians × hours per person'),stat('Project capacity',num(sum(sites,'available_project_hours'),0)+' h','Available site hours'),stat('Completion records','—','Not supplied in workbook'))+panel('Training requirements',requirements)+`<div class="grid-two setup-cards">${panel(supervisor?'Configuration cost inputs':'Reading quality',configuration)}${panel('Digital training · '+o.option_id,training,badge('Workbook option'))}</div>`;
}
const MATRIX=[['Operational dashboard',true,false,false],['Field dashboard',false,true,false],['Safety dashboard',false,false,true],['HSE source records',true,true,true],['Downtime analysis',true,false,false],['Parts readiness',true,true,false],['Training requirements',true,true,true],['Access & Activity',true,false,true],['Operational exports',true,false,false],['HSE export',false,false,true]];
function access(){const readings=selectedSites().map(s=>s.readings);return meta('Application permissions')+stats(stat('Sites in view',selectedSites().length),stat('Source HSE records',hazards().length),stat('Missing readings',sum(readings.map(r=>r.quality_counts),'Missing')),stat('Readings delayed > 1 h',sum(readings,'delayed_over_1h_count')))+`<div class="grid-main">${panel('Role permissions',table(['View / action','Supervisor','Technician','HSE Supervisor'],MATRIX.map(([l,...p])=>`<tr><td>${l}</td>${p.map(v=>`<td class="matrix ${v?'yes':'no'}">${v?icon('check'):'—'}</td>`).join('')}</tr>`)),badge('Interface access'))}${panel('Workbook activity',recentSafety(4),badge('HSE closures'))}</div>`;}
function primaryAction(){if(current==='hse'&&canExport('hse'))return ['Export HSE','hse'];if(state.role==='Supervisor'){const type={dashboard:'operations',downtime:'downtime',parts:'parts',setup:'setup'}[current];if(type)return ['Export report',type];}return null;}
function render(){let requested=location.hash.slice(1)||'dashboard';if(!allowed(requested)){requested='dashboard';history.replaceState(null,'','#dashboard');}current=requested;const title=current==='setup'&&state.role==='Technician'?'Training':PAGES.find(p=>p[0]===current)[2];document.title=title+' | Field Operations';document.getElementById('page-title').textContent=title;document.getElementById('role').value=state.role;document.getElementById('role-avatar').textContent={Supervisor:'SV',Technician:'TC','HSE Supervisor':'HS'}[state.role];document.getElementById('site-scope').innerHTML=`<option value="all">All sites</option>${DATA.sites.map(s=>`<option value="${s.site_id}">${esc(s.site_name)}</option>`).join('')}`;document.getElementById('site-scope').value=state.site;document.getElementById('nav').innerHTML=PAGES.filter(p=>allowed(p[0])).map(([id,i,l])=>`<a href="#${id}" class="${current===id?'active':''}" ${current===id?'aria-current="page"':''}>${icon(i)}<span>${id==='setup'&&state.role==='Technician'?'Training':l}</span>${id==='hse'&&criticalHazards().length?`<b class="nav-count">${criticalHazards().length}</b>`:''}</a>`).join('');const action=primaryAction(),button=document.getElementById('primary-action');button.hidden=!action;button.innerHTML=action?icon('download')+action[0]:'';button.dataset.export=action?action[1]:'';main.innerHTML=({dashboard,hse,downtime,parts,setup,access})[current]();}
